import org.json.JSONArray;
import org.json.JSONObject;
import java.text.DecimalFormat;
import org.joget.apps.datalist.service.DataListService;
import org.joget.apps.app.service.AppUtil;

DataListService dataListService = (DataListService) AppUtil.getApplicationContext().getBean("dataListService");

String jsonStr = value;

try {
    jsonStr = jsonStr.trim();
    if (jsonStr.startsWith("**")) {
        jsonStr = jsonStr.substring(2);
    }
    if (jsonStr.endsWith("**")) {
        jsonStr = jsonStr.substring(0, jsonStr.length() - 2);
    }
    
    JSONArray jsonArray = new JSONArray(jsonStr);
	JSONArray result = new JSONArray();
    
    
    DecimalFormat df = new DecimalFormat("#,##0.##");
    
    for (int i = 0; i < jsonArray.length(); i++) {
        JSONObject product = jsonArray.getJSONObject(i);
		JSONObject productObj = new JSONObject();

        
        productObj.put("product_description", product.optString("product_description", ""));
        productObj.put("product_code", product.optString("product_code", ""));
        productObj.put("uom", product.optString("product_uom", ""));
        productObj.put("hscode", product.optString("product_hscode", ""));
        productObj.put("notes", product.optString("product_other_notes", ""));
        
        // Format number safely
        String qty = product.optString("product_standard_quantity", "");
        try {
            double num = Double.parseDouble(qty);
            productObj.put("standard_quantity", df.format(num));
        } catch (Exception e) {
            productObj.put("standard_quantity", qty);
        }
        
        // Handle raw materials
        JSONArray rawMaterialsArr = new JSONArray();
        String rawMaterialTypeStr = product.optString("raw_material_type", "");
        if (!rawMaterialTypeStr.isEmpty()) {
            try {
                JSONArray rawMaterials = new JSONArray(rawMaterialTypeStr);
                for (int j = 0; j < rawMaterials.length(); j++) {
                    JSONObject rm = rawMaterials.getJSONObject(j);
                    JSONObject rmObj = new JSONObject();
                    
                    rmObj.put("description", rm.optString("raw_material_type_description", ""));
                    rmObj.put("uom", rm.optString("uom", ""));
                    rmObj.put("quantity", rm.optString("quantity", ""));
                    rmObj.put("waste_percentage", rm.optString("waste_percentage", ""));
                    rmObj.put("ioc", rm.optString("input_output_coefficient", ""));
                    rmObj.put("category", rm.optString("raw_material_type_code", ""));
                    
                    // Handle nested inputs
                    String rmInputStr = rm.optString("raw_material_input", "");
                    if (!rmInputStr.isEmpty()) {
                        try {
                            JSONArray inputs = new JSONArray(rmInputStr);
                            rmObj.put("inputs", inputs);
                        } catch (Exception e) {
                            rmObj.put("inputs", new JSONArray());
                        }
                    }
                    
                    rawMaterialsArr.put(rmObj);
                }
            } catch (Exception e) {
                // skip malformed raw materials
            }
        }
        
        productObj.put("raw_materials", rawMaterialsArr);
        result.put(productObj);
    }
    
    if (result.length() == 0) {
        return "{}"; // or "[]" if you prefer
    }
    
    return result.toString(); // pretty print with indentation
    
} catch (Exception e) {
    return "{ \"error\": \"Unable to parse product data - " + e.getMessage() + "\" }";
}
